//! Replays `tests/data/sntrup_vectors.txt`, generated by the Go oracle (see
//! its header), so the crate keeps pinned coverage where no Go toolchain is
//! available. No expected value in it was written by hand.
//!
//! The replay refuses a file that is truncated, edited or stale: the body
//! hash, the entry count and the per-command counts in the header must
//! match, the header must name the parity pin, and the requests must be
//! exactly the corpus `tests/common/mod.rs` builds today from the fixed
//! seed, in order.

#![allow(
    clippy::arithmetic_side_effects,
    clippy::indexing_slicing,
    reason = "test code: arithmetic and indexing on small test values"
)]

mod common;

use std::collections::BTreeMap;

use common::{FROZEN_PLAN, FROZEN_SEED, VECTORS, corpus, read_vectors, resolve, rust_outcome};
use purse_testutil::serde_json::Value;
use purse_testutil::{DCRWALLET_PARITY_COMMIT, SplitMix64};

#[test]
fn replay_frozen_vectors() {
    let (text, entries) = read_vectors();
    assert!(
        text.lines()
            .take_while(|l| l.starts_with('#'))
            .any(|l| l.contains(DCRWALLET_PARITY_COMMIT)),
        "{VECTORS} does not name dcrwallet {DCRWALLET_PARITY_COMMIT}"
    );
    let expected = corpus(&mut SplitMix64(FROZEN_SEED), FROZEN_PLAN);
    assert_eq!(
        entries.len(),
        expected.len(),
        "{VECTORS} holds {} entries, the corpus has {}: regenerate it",
        entries.len(),
        expected.len()
    );
    let recorded: Vec<Value> = entries.iter().map(|e| e.outcome.clone()).collect();
    let mut per_label: BTreeMap<&str, usize> = BTreeMap::new();
    for (i, (e, want)) in entries.iter().zip(&expected).enumerate() {
        assert_eq!(
            (e.cmd.as_str(), &e.args),
            (want.cmd.as_str(), &want.args),
            "entry {i}: the request differs from the corpus: regenerate {VECTORS}"
        );
        let args = resolve(&e.args, &recorded[..i]);
        assert_eq!(
            rust_outcome(&e.cmd, &args),
            e.outcome,
            "entry {i} ({}, {}): Rust differs from the recorded Go outcome",
            e.cmd,
            want.label
        );
        *per_label.entry(want.label).or_default() += 1;
    }
    eprintln!("{per_label:?}");
    for label in [
        "keygen",
        "keygen-short",
        "keygen-retry",
        "encapsulate",
        "encapsulate-short",
        "encapsulate-bad-pk",
        "decapsulate",
        "decapsulate-tampered",
        "decapsulate-moved-coefficient",
        "decapsulate-wrong-weight",
        "decapsulate-alias",
        "decapsulate-wrong-key",
        "decapsulate-bad-sk",
        "decapsulate-random",
        "decapsulate-random-ct",
    ] {
        assert!(
            per_label.contains_key(label),
            "no frozen entry of kind {label}"
        );
    }
}

/// Go's outcomes recorded for the tail aliases are valid decapsulations to
/// the honest ciphertext's key (QK-0740); those recorded for the
/// ciphertexts that fail one check alone are invalid, with the key of the
/// r they were built from; and every error text Go can give for a short
/// stream is pinned.
#[test]
fn recorded_outcomes_pin_the_quirk_and_the_errors() {
    let (_, entries) = read_vectors();
    let expected = corpus(&mut SplitMix64(FROZEN_SEED), FROZEN_PLAN);
    let mut aliases = 0;
    let mut single = 0;
    let mut texts = std::collections::BTreeSet::new();
    for (e, r) in entries.iter().zip(&expected) {
        if r.label == "decapsulate-alias" {
            assert_eq!(e.outcome["ok"]["ok"], 1, "Go rejected a tail alias");
            aliases += 1;
        }
        if let Some(key) = &r.expect_key {
            assert_eq!(e.outcome["ok"]["ok"], 0, "Go accepted a {}", r.label);
            assert_eq!(e.outcome["ok"]["key"], *key, "{}", r.label);
            single += 1;
        }
        if let Some(t) = e.outcome["err"]["text"].as_str() {
            texts.insert(t.split('\t').next().unwrap_or_default().to_owned());
        }
    }
    assert!(aliases > 0);
    assert!(single > 0);
    assert_eq!(
        texts.into_iter().collect::<Vec<_>>(),
        ["EOF", "unexpected EOF"],
        "the error texts recorded"
    );
}

#[test]
#[should_panic(expected = "body hash")]
fn a_changed_body_fails_the_integrity_check() {
    let (text, _) = read_vectors();
    // Change one hex digit of the last line.
    let mut lines: Vec<String> = text.lines().map(str::to_owned).collect();
    let last = lines.last_mut().expect("a body line");
    let pos = last.rfind(|c: char| c.is_ascii_hexdigit()).expect("hex");
    let c = last.as_bytes()[pos];
    last.replace_range(pos..=pos, if c == b'0' { "1" } else { "0" });
    common::verify_vectors(&(lines.join("\n") + "\n"));
}
